@@ -0,0 +1,16 @@
+import { Manifest, Platform } from "./manifest";
+
+export class Session {
+  platform: Platform | null;
+  messages: string[];
+
+  constructor(manifest: Manifest) {
+    this.platform = manifest.platform;
+    this.messages = manifest.platform?.messages ?? [];
+  }
+
+  apply(manifest: Manifest): void {
+    this.platform = manifest.platform;
+    this.messages = manifest.platform?.messages ?? [];
+  }
+}

@@ -0,0 +1,9 @@
+export interface Platform {
+  name: string;
+  messages: string[];
+}
+
+export interface Manifest {
+  version: number;
+  platform: Platform | null;
+}

